import{_ as a,c as t,o as n,ag as r}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Performance hometasks","description":"","frontmatter":{},"headers":[],"relativePath":"practice/frontend/performance/index.md","filePath":"practice/frontend/performance/index.md"}'),i={name:"practice/frontend/performance/index.md"};function s(o,e,d,l,c,p){return n(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="performance-hometasks" tabindex="-1">Performance hometasks <a class="header-anchor" href="#performance-hometasks" aria-label="Permalink to “Performance hometasks”">​</a></h1><p><strong>All learner work is outstanding.</strong> These three core hometasks apply the <a href="./../../../frontend/performance/">performance learning path</a> to one course catalogue or the existing P-328/P-329 product. They refine <a href="./../../engineering/e02.html">E02 — Measured performance</a>, rather than adding another mandatory application.</p><h2 id="required-sequence" tabindex="-1"><span class="hub-section-number">1 </span>Required sequence <a class="header-anchor" href="#required-sequence" aria-label="Permalink to “1 Required sequence”">​</a></h2><table tabindex="0"><thead><tr><th>Hometask</th><th>Prerequisites</th><th>Deliverable</th></tr></thead><tbody><tr><td><a href="./01-investigate.html">H1 — Investigate a slow journey</a></td><td>Working browser application; measurement and loading lessons</td><td>Reproducible baseline, causal trace and prioritized hypotheses</td></tr><tr><td><a href="./02-improve.html">H2 — Improve loading and interaction</a></td><td>H1; image/CSS/bundle and runtime lessons as applicable</td><td>One loading intervention and one interaction intervention, evaluated independently</td></tr><tr><td><a href="./03-verify.html">H3 — Verify and prevent regressions</a></td><td>H2; cache/delivery lesson</td><td>Comparable final evidence, a working regression check and a monitoring/release plan</td></tr></tbody></table><p>H1 can begin after HTML/CSS/JavaScript foundations. The interaction intervention can use native DOM or React after F05; Next/SSR comparisons follow F06. Keep the same dataset and user journeys across stages. Expand a tiny fixture with deterministic public/generated records when necessary; record the generator seed and data volume. Do not introduce private customer data or deliberately expensive work into a real product.</p><p>You do not need to implement every optimization. Choose a cause observed in the trace. If a plausible experiment fails to improve the outcome, retain that evidence, explain the result and revert the ineffective change. H2 still requires trying both intervention categories; a well-supported rejection is acceptable evidence, not an invitation to invent gains.</p><h2 id="shared-hand-in-structure" tabindex="-1"><span class="hub-section-number">2 </span>Shared hand-in structure <a class="header-anchor" href="#shared-hand-in-structure" aria-label="Permalink to “2 Shared hand-in structure”">​</a></h2><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>performance-evidence/</span></span>
<span class="line"><span>  README.md              # revision, setup, journeys, environment and reproduction</span></span>
<span class="line"><span>  baseline/              # raw runs, reports, trace or sanitized HAR</span></span>
<span class="line"><span>  experiments/           # one folder per intervention and its measured runs</span></span>
<span class="line"><span>  final/                 # comparable final runs and behavior checks</span></span>
<span class="line"><span>  report.md              # causal explanation, trade-offs, limits and decision</span></span></code></pre></div><p>Keep source changes small and reviewable in the existing app. Link the exact revision or local diff in the report. The folder layout is suggested; the evidence and reproducibility are required. Do not commit secrets, personal data or authenticated HAR bodies. Use a public lab or sanitize exports.</p><p>Each report follows <strong>before → hypothesis → change → evidence → trade-off</strong>. Label measured values, illustrative values, unperformed checks and planned production observations distinctly. All raw trials count; do not present only the best score.</p><h2 id="completion-criteria" tabindex="-1"><span class="hub-section-number">3 </span>Completion criteria <a class="header-anchor" href="#completion-criteria" aria-label="Permalink to “3 Completion criteria”">​</a></h2><ul><li>Another learner can reproduce the baseline and experiment from recorded setup and steps.</li><li>A trace connects the selected cause to the user-visible delay; file-size or render-count evidence alone is insufficient.</li><li>The page remains correct, readable and keyboard usable under the declared failure cases.</li><li>Results distinguish cold/warm runs, local/synthetic evidence and field data; no field p75 is inferred from a handful of lab trials.</li><li>A regression check demonstrably catches an intentional local regression and passes after restoration.</li><li>Remaining device, accessibility, browser and production gaps are stated honestly.</li></ul><p>There is no universal Lighthouse-score pass mark or imported lateness penalty. H1–H3 are required practice checkpoints for this learning path; reading or copying a worked example does not complete them.</p><h2 id="optional-extensions" tabindex="-1"><span class="hub-section-number">4 </span>Optional extensions <a class="header-anchor" href="#optional-extensions" aria-label="Permalink to “4 Optional extensions”">​</a></h2><table tabindex="0"><thead><tr><th>Extension</th><th>Exercise</th><th>Additional evidence</th></tr></thead><tbody><tr><td>Browser-target / differential build</td><td>Adapt EPAM&#39;s Babel/Webpack task; record resolved modern/legacy targets and syntax/API policy</td><td>Three comparable bundle variants, equivalent behavior and both supported target paths; explain <code>module</code>/<code>nomodule</code> limits</td></tr><tr><td>Responsive compatibility</td><td>Generate 320/768/1024/1920 candidates; supply WebP/JPEG, optionally AVIF; conditionally handle missing native lazy loading</td><td>Fresh navigations at multiple DPRs, <code>currentSrc</code>, no blank images without enhancement, eager LCP</td></tr><tr><td>Critical-CSS automation and fonts</td><td>Extract initial rules for narrow/tablet/wide views; compare Roboto/Raleway with a smaller/system alternative using licensed assets</td><td>Dialog/error/focus states, no-JS/CSP behavior, fonts delayed/failed, supported accents, 200% text</td></tr><tr><td>Webpack dependency analysis</td><td>Two entries using Lodash; analyze full, deep-import and ESM variants, shared chunks and production output</td><td>Equivalent results, actual dependency graph, initial/feature bytes, required side effects retained</td></tr><tr><td>Dedicated Web Worker</td><td>Move a bounded calculation off the page thread; compare against main-thread/chunked alternatives</td><td>Equal output, input remains usable, message/startup costs, stale reply/error/termination cases</td></tr><tr><td>Offline service worker</td><td>Cache public versioned assets with an explicit update policy</td><td>Install/control/update, failed precache, old tab/new deployment, eviction/offline recovery, no private-response caching</td></tr><tr><td>SSR/streaming or large-list architecture</td><td>Compare an observed CSR/hydration or DOM-volume bottleneck</td><td>Server and browser costs, meaningful HTML, first interaction, focus/selection and failure recovery</td></tr></tbody></table><p>These are modernized local exercises. The original EPAM template&#39;s exact plugin names, output filenames and marked-comment rules apply only when undertaking that original assignment. Completing a local extension does not claim a passing EPAM submission. Infrastructure setup and original private-repository access are not required for H1–H3.</p><p><a href="./01-investigate.html">Start H1</a> · <a href="./../../../frontend/performance/">Reading path</a> · <a href="./../../engineering/performance/">Existing focused performance cases</a></p>`,17)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
